+        gap: 0.4rem 0.75rem;
+        border: 1px solid var(--border);
+        border-radius: 1rem;
+        padding: 1rem;
+        background: var(--surface-muted);
+      }
+
+      .form-field:focus-within {
+        border-color: var(--primary);
+        box-shadow: 0 0 0 4px rgba(36, 87, 214, 0.16);
+      }
+
+      input[type="checkbox"] {
+        width: 1.35rem;
+        height: 1.35rem;
+        margin: 0.1rem 0 0;
+        accent-color: var(--primary);
+        cursor: pointer;
+      }
+
+      input[type="checkbox"]:focus-visible,
+      button:focus-visible {
+        outline: 3px solid var(--focus);
+        outline-offset: 3px;
+      }
+
+      label {
+        font-size: 1rem;
+        font-weight: 700;
+        line-height: 1.45;
+        cursor: pointer;
+      }
+
+      .required {
+        color: var(--danger);
+        font-weight: 800;
+      }
+
+      .helper-text,
+      .error-text {
+        grid-column: 2;
+        margin: 0;
+        font-size: 0.925rem;
+        line-height: 1.45;
+      }
+
+      .helper-text {
+        color: var(--muted);
+      }
+
+      .error-text {
+        color: var(--danger);
+        font-weight: 700;
+      }
+
+      .error-text[hidden] {
+        display: none;
+      }
+
+      button {
+        width: 100%;
+        min-height: 3rem;
+        margin-top: 1rem;
+        border: 0;
+        border-radius: 999px;
+        padding: 0.85rem 1.25rem;
+        color: var(--primary-text);
+        background: var(--primary);
+        box-shadow: 0 12px 24px rgba(36, 87, 214, 0.25);
+        font: inherit;
+        font-weight: 800;
+        cursor: pointer;
+      }
+
+      button:hover {
+        background: var(--primary-hover);
+      }
+
+      .status {
+        min-height: 1.5rem;
+        margin: 1rem 0 0;
+        color: #166534;
+        font-size: 0.95rem;
+        font-weight: 700;
+        line-height: 1.4;
+      }
+
+      @media (forced-colors: active) {
+        .card,
+        .form-field,
+        button {
+          border: 1px solid CanvasText;
+          box-shadow: none;
+        }
+
+        button {
+          color: ButtonText;
+          background: ButtonFace;
+        }
+      }
+    </style>
+  </head>
+  <body>
+    <a class="skip-link" href="#main-content">Skip to main content</a>
+    <div id="root"></div>
+
+    <script>
+      const components = {
+        App() {
+          return `
+            <main id="main-content">
+              <section class="card" aria-labelledby="page-title">
+                ${components.FormHeader()}
+                ${components.ConsentForm()}
+              </section>
+            </main>
+          `;
+        },
+        FormHeader() {
+          return `
+            <p class="eyebrow">Account setup</p>
+            <h1 id="page-title">Review terms</h1>
+            <p class="lede">Confirm that you accept the terms of use before continuing.</p>
+          `;
+        },
+        ConsentForm() {
+          return `
+            <form id="terms-form" novalidate>
+              ${components.CheckboxField()}
+              <button type="submit">Continue</button>
+              <p class="status" id="form-status" aria-live="polite"></p>
+            </form>
+          `;
+        },
+        CheckboxField() {
+          return `
+            <div class="form-field">
+              <input
+                id="terms-consent"
+                name="terms-consent"
+                type="checkbox"
+                required
+                aria-describedby="terms-helper terms-error"
+              >
+              <label for="terms-consent">
+                I agree to the terms of use <span class="required" aria-hidden="true">*</span>
+              </label>
+              <p class="helper-text" id="terms-helper">Required to create and use your account.</p>
+              <p class="error-text" id="terms-error" hidden>Error: You must agree to the terms of use to continue.</p>
+            </div>
+          `;
+        }
+      };
+
+      document.getElementById("root").innerHTML = components.App();
+
+      const form = document.getElementById("terms-form");
+      const checkbox = document.getElementById("terms-consent");
+      const error = document.getElementById("terms-error");
+      const status = document.getElementById("form-status");
+
+      function setConsentError(isInvalid) {
+        checkbox.setAttribute("aria-invalid", String(isInvalid));
+        error.hidden = !isInvalid;
+      }
+
+      form.addEventListener("submit", (event) => {
+        event.preventDefault();
+        status.textContent = "";
+
+        if (!checkbox.checked) {
+          setConsentError(true);
+          checkbox.focus();
+          return;
+        }
+
+        setConsentError(false);
+        status.textContent = "Thanks. Your consent has been recorded.";
+      });
+
+      checkbox.addEventListener("change", () => {
+        if (checkbox.checked) {
+          setConsentError(false);
+        }
+      });
+    </script>
+  </body>
+</html>
*** End Patch
