<html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Terms Consent Form</title>
    <style>
      :root {
        color-scheme: light;
        --background: #eef2ff;
        --surface: #ffffff;
        --surface-muted: #f8fafc;
        --text: #111827;
        --muted: #4b5563;
        --border: #cbd5e1;
        --primary: #2457d6;
        --primary-hover: #1d4cc1;
        --primary-text: #ffffff;
        --danger: #b42318;
        --focus: #f59e0b;
        --shadow: 0 24px 70px rgba(15, 23, 42, 0.16);
      }

      * {
        box-sizing: border-box;
      }

      body {
        min-height: 100vh;
        margin: 0;
        font-family:
          Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top left, rgba(36, 87, 214, 0.18), transparent 32rem),
          linear-gradient(135deg, #f8fafc 0%, var(--background) 100%);
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        z-index: 10;
        transform: translateY(-150%);
        border-radius: 999px;
        padding: 0.75rem 1rem;
        color: var(--primary-text);
        background: var(--primary);
        font-weight: 700;
      }

      .skip-link:focus {
        transform: translateY(0);
        outline: 3px solid var(--focus);
        outline-offset: 3px;
      }

      main {
        display: grid;
        min-height: 100vh;
        place-items: center;
        padding: 2rem 1rem;
      }

      .card {
        width: min(100%, 31rem);
        border: 1px solid rgba(203, 213, 225, 0.9);
        border-radius: 1.5rem;
        padding: clamp(1.5rem, 5vw, 2.5rem);
        background: var(--surface);
        box-shadow: var(--shadow);
      }

      .eyebrow {
        margin: 0 0 0.75rem;
        color: var(--primary);
        font-size: 0.875rem;
        font-weight: 800;
        letter-spacing: 0.08em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 7vw, 3rem);
        line-height: 1;
        letter-spacing: -0.05em;
      }

      .lede {
        margin: 1rem 0 0;
        color: var(--muted);
        font-size: 1rem;
        line-height: 1.6;
      }

      form {
        margin-top: 2rem;
      }

      .form-field {
        display: grid;
        grid-template-columns: auto 1fr;
        gap: 0.4rem 0.75rem;
        border: 1px solid var(--border);
        border-radius: 1rem;
        padding: 1rem;
        background: var(--surface-muted);
      }

      .form-field:focus-within {
        border-color: var(--primary);
        box-shadow: 0 0 0 4px rgba(36, 87, 214, 0.16);
      }

      input[type="checkbox"] {
        width: 1.35rem;
        height: 1.35rem;
        margin: 0.1rem 0 0;
        accent-color: var(--primary);
        cursor: pointer;
      }

      input[type="checkbox"]:focus-visible,
      button:focus-visible {
        outline: 3px solid var(--focus);
        outline-offset: 3px;
      }

      label {
        font-size: 1rem;
        font-weight: 700;
        line-height: 1.45;
        cursor: pointer;
      }

      .required {
        color: var(--danger);
        font-weight: 800;
      }

      .helper-text,
      .error-text {
        grid-column: 2;
        margin: 0;
        font-size: 0.925rem;
        line-height: 1.45;
      }

      .helper-text {
        color: var(--muted);
      }

      .error-text {
        color: var(--danger);
        font-weight: 700;
      }

      .error-text[hidden] {
        display: none;
      }

      button {
        width: 100%;
        min-height: 3rem;
        margin-top: 1rem;
        border: 0;
        border-radius: 999px;
        padding: 0.85rem 1.25rem;
        color: var(--primary-text);
        background: var(--primary);
        box-shadow: 0 12px 24px rgba(36, 87, 214, 0.25);
        font: inherit;
        font-weight: 800;
        cursor: pointer;
      }

      button:hover {
        background: var(--primary-hover);
      }

      .status {
        min-height: 1.5rem;
        margin: 1rem 0 0;
        color: #166534;
        font-size: 0.95rem;
        font-weight: 700;
        line-height: 1.4;
      }

      @media (forced-colors: active) {
        .card,
        .form-field,
        button {
          border: 1px solid CanvasText;
          box-shadow: none;
        }

        button {
          color: ButtonText;
          background: ButtonFace;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div id="root"></div>

    <script>
      const components = {
        App() {
          return `
            <main id="main-content">
              <section class="card" aria-labelledby="page-title">
                ${components.FormHeader()}
                ${components.ConsentForm()}
              </section>
            </main>
          `;
        },
        FormHeader() {
          return `
            <p class="eyebrow">Account setup</p>
            <h1 id="page-title">Review terms</h1>
            <p class="lede">Confirm that you accept the terms of use before continuing.</p>
          `;
        },
        ConsentForm() {
          return `
            <form id="terms-form" novalidate>
              ${components.CheckboxField()}
              <button type="submit">Continue</button>
              <p class="status" id="form-status" aria-live="polite"></p>
            </form>
          `;
        },
        CheckboxField() {
          return `
            <div class="form-field">
              <input
                id="terms-consent"
                name="terms-consent"
                type="checkbox"
                required
                aria-describedby="terms-helper terms-error"
              >
              <label for="terms-consent">
                I agree to the terms of use <span class="required" aria-hidden="true">*</span>
              </label>
              <p class="helper-text" id="terms-helper">Required to create and use your account.</p>
              <p class="error-text" id="terms-error" hidden>Error: You must agree to the terms of use to continue.</p>
            </div>
          `;
        }
      };

      document.getElementById("root").innerHTML = components.App();

      const form = document.getElementById("terms-form");
      const checkbox = document.getElementById("terms-consent");
      const error = document.getElementById("terms-error");
      const status = document.getElementById("form-status");

      function setConsentError(isInvalid) {
        checkbox.setAttribute("aria-invalid", String(isInvalid));
        error.hidden = !isInvalid;
      }

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        status.textContent = "";

        if (!checkbox.checked) {
          setConsentError(true);
          checkbox.focus();
          return;
        }

        setConsentError(false);
        status.textContent = "Thanks. Your consent has been recorded.";
      });

      checkbox.addEventListener("change", () => {
        if (checkbox.checked) {
          setConsentError(false);
        }
      });
    </script>
  </body>
</html>
