              </label>
              <p class="helper-text" id="terms-helper">Required to create and use your account.</p>
              <p class="error-text" id="terms-error" hidden>Error: You must agree to the terms of use to continue.</p>
            </div>
          `;
        }
      };

      document.getElementById("root").innerHTML = components.App();

      const form = document.getElementById("terms-form");
      const checkbox = document.getElementById("terms-consent");
      const error = document.getElementById("terms-error");
      const status = document.getElementById("form-status");

      function setConsentError(isInvalid) {
        if (isInvalid) {
          checkbox.setAttribute("aria-invalid", "true");
